1	/**
2	 * What a lesson *serves* — and the schema the in-house decks are written to.
3	 *
4	 * The content-source seam: `LessonContent` is a two-arm discriminated union so
5	 * a lesson can serve either a licensed `.webm` or an in-house deck, one lesson
6	 * at a time, with the compiler refusing any dispatch that forgets an arm.
7	 *
8	 * The deck schema's one non-structural demand is **retrieval**: a deck is
9	 * invalid unless the learner is asked to attempt something before the answer
10	 * is shown. A guideline would be honoured by the first deck and forgotten by
11	 * the twelfth; a schema rule is checked on every deck for free.
12	 */
13	
14	import {
15		type LessonSequenceEntry,
16		lessonEntryById,
17		parseLessonId,
18	} from "./lessonSequence";
19	import { type Lesson, lessons, specialRules, toneRules } from "./symbols";
20	
21	// ============================================================================
22	// The content union
23	// ============================================================================
24	
25	export type LessonContent =
26		| { readonly kind: "video"; readonly url: string }
27		| { readonly kind: "deck"; readonly deckPath: string };
28	
29	/**
30	 * Exhaustive dispatch over `LessonContent`. The `never` default is the point:
31	 * adding a third arm without handling it here is a compile error, which is how
32	 * every downstream dispatch is kept honest too.
33	 */
34	export function describeLessonContent(content: LessonContent): string {
35		switch (content.kind) {
36			case "video":
37				return `video ${content.url}`;
38			case "deck":
39				return `deck ${content.deckPath}`;
40			default: {
41				const _never: never = content;
42				return _never;
43			}
44		}
45	}
46	
47	// ============================================================================
48	// Asset paths
49	// ============================================================================
50	
51	/**
52	 * Public root under which every generated lesson asset lives. Includes the
53	 * app's deploy base path (`vite.config.ts`'s `base: "/thai-script/"`) —
54	 * every other asset URL in this codebase (`symbols.ts`'s `videoUrl` and
55	 * `audioUrl` fields) is hardcoded the same way, and a root that omits it
56	 * 404s once the app is actually served under that base, dev included.
57	 */
58	export const LESSON_ASSET_ROOT = "/thai-script/lessons";
59	
60	export type DeckPathResult =
61		| { readonly ok: true; readonly path: string }
62		| { readonly ok: false; readonly error: string };
63	
64	/**
65	 * The one place a filesystem/URL path is derived from a lesson id, and so the
66	 * one place the charset has to hold. Task 1.3 owns the containment check at
67	 * the generator's write boundary; this owns the charset.
68	 */
69	export function deckPathForLesson(
70		value: unknown,
71		key = "lessonId",
72	): DeckPathResult {
73		const parsed = parseLessonId(value, key);
74		if (!parsed.ok) return parsed;
75		return { ok: true, path: `${LESSON_ASSET_ROOT}/${parsed.id}/deck.json` };
76	}
77	
78	// ============================================================================
79	// Resolution — three states, and "unresolvable" never reads as "undeclared"
80	// ============================================================================
81	
82	/**
83	 * Lessons whose content is an in-house deck. The strangler grew this set one
84	 * band at a time from task 1.4's `lesson-01`; task 4.3 closed it — every
85	 * declared lesson is here, and no lesson resolves to the video arm any more.
86	 *
87	 * `lesson-sound-buckets` is deliberately absent: it has no `legacyNumber` in
88	 * `lessonSequence.ts`, and giving it one is a lesson-identity decision
89	 * (CONTEXT.md Rule 1 — the five-store hazard) that belongs with the task
90	 * that owns that migration, not a one-line addition here. Its deck is
91	 * committed and schema-valid (see `openingBand.test.ts`) but unreachable
92	 * from any route until that sequencing decision is made.
93	 */
94	export const DECK_LESSON_IDS: ReadonlySet<string> = new Set<string>([
95		"lesson-01",
96		"lesson-02",
97		"lesson-03",
98		"lesson-04",
99		"lesson-05",
100		// Phase 3's middle band.
101		"lesson-06",
102		"lesson-07",
103		"lesson-08",
104		"lesson-09",
105		"lesson-10",
106		"lesson-11",
107		// Task 4.3's final band — the three lessons that replaced the last
108		// fourteen video slots — and the optional numerals track.
109		"lesson-12",
110		"lesson-13",
111		"lesson-14",
112		"lesson-numerals",
113		// Phase 3's three promoted lessons.
114		"lesson-unwritten-vowels",
115		"lesson-clusters",
116		"lesson-leading-consonants",
117		// Task 4.2 — the consolidated tone-mark lesson.
118		"lesson-tone-marks",
119	]);
120	
121	export type LessonContentResolution =
122		/** Declared, and its content source is known. */
123		| { readonly status: "resolved"; readonly content: LessonContent }
124		/** Declared, but no content source can be produced — with the reason. */
125		| { readonly status: "unresolvable"; readonly reason: string }
126		/** No lesson with this id is declared at all. */
127		| { readonly status: "undeclared" };
128	
129	/**
130	 * The three statuses are distinct values on purpose: a lesson whose video is
131	 * missing must never be indistinguishable from a lesson that does not exist,
132	 * because the first is a broken build and the second is an ordinary 404.
133	 */
134	export const LESSON_CONTENT_STATUSES = [
135		"resolved",
136		"unresolvable",
137		"undeclared",
138	] as const;
139	
140	/**
141	 * Content for a lesson that is known to be declared, so the only two outcomes
142	 * left are "resolved" and "unresolvable". Split out from `resolveLessonContent`
143	 * because the undeclared case is decided by the lookup and this one is not —
144	 * a lesson whose video went missing must never read as a lesson that does not
145	 * exist.
146	 */
147	export function lessonContentFor(
148		entry: LessonSequenceEntry,
149		lesson: Lesson | undefined,
150	): LessonContentResolution {
151		if (DECK_LESSON_IDS.has(entry.id)) {
152			const path = deckPathForLesson(entry.id);
153			if (!path.ok) return { status: "unresolvable", reason: path.error };
154			return {
155				status: "resolved",
156				content: { kind: "deck", deckPath: path.path },
157			};
158		}
159		if (!lesson) {
160			return {
161				status: "unresolvable",
162				reason:
163					"lessonId: declared in the sequence but absent from the lessons table",
164			};
165		}
166		if (!lesson.videoUrl) {
167			return {
168				status: "unresolvable",
169				reason: "lessonId: declares neither a deck nor a video url",
170			};
171		}
172		return {
173			status: "resolved",
174			content: { kind: "video", url: lesson.videoUrl },
175		};
176	}
177	
178	export function resolveLessonContent(value: unknown): LessonContentResolution {
179		const lookup = lessonEntryById(value);
180		if (!lookup.ok) return { status: "undeclared" };
181		const entry = lookup.entry;
182		return lessonContentFor(
183			entry,
184			lessons.find((lesson) => lesson.number === entry.legacyNumber),
185		);
186	}
187	
188	// ============================================================================
189	// The rules block
190	// ============================================================================
191	
192	/**
193	 * A rule a lesson teaches, resolved from the tables that already declare it
194	 * (`toneRules`, `specialRules`) via the ids the lessons table already lists.
195	 * Rule slides render from this — they carry no prose of their own, so the
196	 * slide and the rule cannot drift apart.
197	 */
198	export interface LessonRule {
199		readonly id: string;
200		readonly kind: "tone" | "special";
201		readonly title: string;
202		readonly text: string;
203	}
204	
205	export function lessonRules(legacyNumber: number): readonly LessonRule[] {
206		const lesson = lessons.find((candidate) => candidate.number === legacyNumber);
207		if (!lesson) return [];
208	
209		const tone = lesson.toneRulesIntroduced.flatMap<LessonRule>((id) => {
210			const rule = toneRules.find((candidate) => candidate.id === id);
211			if (!rule) return [];
212			return [
213				{
214					id: rule.id,
215					kind: "tone",
216					title: `${rule.consonantClass} class + ${rule.syllableType} syllable = ${rule.resultingTone} tone`,
217					text: rule.description,
218				},
219			];
220		});
221		const special = lesson.specialRulesIntroduced.flatMap<LessonRule>((id) => {
222			const rule = specialRules.find((candidate) => candidate.id === id);
223			if (!rule) return [];
224			return [
225				{
226					id: rule.id,
227					kind: "special",
228					title: rule.title,
229					text: rule.description,
230				},
231			];
232		});
233		return [...tone, ...special];
234	}
235	
236	// ============================================================================
237	// The deck schema
238	// ============================================================================
239	
240	export interface DeckExpositionSlide {
241		readonly kind: "exposition";
242		readonly id: string;
243		readonly heading: string;
244		readonly body: readonly string[];
245	}
246	
247	/**
248	 * A prompt the learner attempts. It names the reveal that answers it and
249	 * carries no answer itself — the attempt is the mechanism, so an answer
250	 * sitting on the same slide defeats the slide entirely.
251	 */
252	export interface DeckRetrievalSlide {
253		readonly kind: "retrieval";
254		readonly id: string;
255		readonly prompt: string;
256		readonly revealSlideId: string;
257	}
258	
259	export interface DeckRevealSlide {
260		readonly kind: "reveal";
261		readonly id: string;
262		readonly retrievalSlideId: string;
263		readonly answers: readonly string[];
264	}
265	
266	/** Renders from the lesson's rules block; holds no prose of its own. */
267	export interface DeckRuleSlide {
268		readonly kind: "rule";
269		readonly id: string;
270		readonly ruleId: string;
271	}
272	
273	export type DeckSlide =
274		| DeckExpositionSlide
275		| DeckRetrievalSlide
276		| DeckRevealSlide
277		| DeckRuleSlide;
278	
279	export interface LessonDeck {
280		readonly lessonId: string;
281		readonly title: string;
282		readonly slides: readonly DeckSlide[];
283	}
284	
285	export type DeckErrorCode =
286		| "malformed"
287		| "lesson-id-refused"
288		| "duplicate-slide-id"
289		| "retrieval-answer-on-same-slide"
290		| "dangling-reveal"
291		| "reveal-before-retrieval"
292		| "missing-retrieval"
293		| "unknown-rule"
294		| "rule-slide-carries-prose";
295	
296	export interface DeckValidationError {
297		readonly code: DeckErrorCode;
298		readonly message: string;
299		readonly slideId?: string;
300	}
301	
302	export type DeckValidationResult =
303		| { readonly ok: true; readonly deck: LessonDeck }
304		| { readonly ok: false; readonly errors: readonly DeckValidationError[] };
305	
306	/** Keys that would put an answer on the retrieval slide itself. */
307	const ANSWER_KEYS = ["answer", "answers", "reveal", "solution"] as const;
308	/** Keys that would let a rule slide state a rule differently from the block. */
309	const PROSE_KEYS = ["heading", "body", "text", "description"] as const;
310	
311	function isRecord(value: unknown): value is Record<string, unknown> {
312		return typeof value === "object" && value !== null && !Array.isArray(value);
313	}
314	
315	function isStringArray(value: unknown): value is string[] {
316		return (
317			Array.isArray(value) && value.every((item) => typeof item === "string")
318		);
319	}
320	
321	function parseSlide(
322		raw: unknown,
323		index: number,
324		errors: DeckValidationError[],
325	): DeckSlide | undefined {
326		const at = `slides[${index}]`;
327		if (!isRecord(raw)) {
328			errors.push({ code: "malformed", message: `${at}: not an object` });
329			return undefined;
330		}
331		const id = raw.id;
332		if (typeof id !== "string" || id.length === 0) {
333			errors.push({ code: "malformed", message: `${at}: missing a string id` });
334			return undefined;
335		}
336	
337		switch (raw.kind) {
338			case "exposition": {
339				if (typeof raw.heading !== "string" || !isStringArray(raw.body)) {
340					errors.push({
341						code: "malformed",
342						slideId: id,
343						message: `${at}: an exposition slide needs a heading and a body of strings`,
344					});
345					return undefined;
346				}
347				return { kind: "exposition", id, heading: raw.heading, body: raw.body };
348			}
349			case "retrieval": {
350				if (
351					typeof raw.prompt !== "string" ||
352					typeof raw.revealSlideId !== "string"
353				) {
354					errors.push({
355						code: "malformed",
356						slideId: id,
357						message: `${at}: a retrieval slide needs a prompt and a revealSlideId`,
358					});
359					return undefined;
360				}
361				const leaked = ANSWER_KEYS.find((key) => key in raw);
362				if (leaked) {
363					errors.push({
364						code: "retrieval-answer-on-same-slide",
365						slideId: id,
366						message: `${at}: retrieval slide carries "${leaked}"; the answer must live on the reveal slide it names, not beside the prompt`,
367					});
368					return undefined;
369				}
370				return {
371					kind: "retrieval",
372					id,
373					prompt: raw.prompt,
374					revealSlideId: raw.revealSlideId,
375				};
376			}
377			case "reveal": {
378				if (
379					typeof raw.retrievalSlideId !== "string" ||
380					!isStringArray(raw.answers)
381				) {
382					errors.push({
383						code: "malformed",
384						slideId: id,
385						message: `${at}: a reveal slide needs a retrievalSlideId and answers`,
386					});
387					return undefined;
388				}
389				return {
390					kind: "reveal",
391					id,
392					retrievalSlideId: raw.retrievalSlideId,
393					answers: raw.answers,
394				};
395			}
396			case "rule": {
397				if (typeof raw.ruleId !== "string") {
398					errors.push({
399						code: "malformed",
400						slideId: id,
401						message: `${at}: a rule slide needs a ruleId`,
402					});
403					return undefined;
404				}
405				const prose = PROSE_KEYS.find((key) => key in raw);
406				if (prose) {
407					errors.push({
408						code: "rule-slide-carries-prose",
409						slideId: id,
410						message: `${at}: rule slide carries "${prose}"; a rule slide renders from the lesson's rules block so the two cannot disagree`,
411					});
412					return undefined;
413				}
414				return { kind: "rule", id, ruleId: raw.ruleId };
415			}
416			default:
417				errors.push({
418					code: "malformed",
419					slideId: id,
420					message: `${at}: unknown slide kind`,
421				});
422				return undefined;
423		}
424	}
425	
426	function checkRetrieval(
427		slides: readonly DeckSlide[],
428		errors: DeckValidationError[],
429	): void {
430		const retrievalsSeen = new Set<string>();
431		let pairs = 0;
432	
433		for (const slide of slides) {
434			if (slide.kind === "retrieval") {
435				retrievalsSeen.add(slide.id);
436				continue;
437			}
438			if (slide.kind !== "reveal") continue;
439	
440			const target = slides.find(
441				(candidate) =>
442					candidate.kind === "retrieval" &&
443					candidate.id === slide.retrievalSlideId,
444			);
445			if (!target) {
446				errors.push({
447					code: "dangling-reveal",
448					slideId: slide.id,
449					message: `reveal "${slide.id}" names no retrieval slide that exists`,
450				});
451				continue;
452			}
453			if (!retrievalsSeen.has(slide.retrievalSlideId)) {
454				errors.push({
455					code: "reveal-before-retrieval",
456					slideId: slide.id,
457					message: `reveal "${slide.id}" comes before the retrieval step it answers; the learner must attempt first`,
458				});
459				continue;
460			}
461			pairs += 1;
462		}
463	
464		if (pairs === 0) {
465			errors.push({
466				code: "missing-retrieval",
467				message:
468					"deck has no retrieval step before a reveal: a deck must ask the learner to attempt at least one answer before showing it",
469			});
470		}
471	}
472	
473	export function validateDeck(value: unknown): DeckValidationResult {
474		const errors: DeckValidationError[] = [];
475	
476		if (!isRecord(value)) {
477			return {
478				ok: false,
479				errors: [{ code: "malformed", message: "deck: not an object" }],
480			};
481		}
482		const lessonId = parseLessonId(value.lessonId, "lessonId");
483		if (!lessonId.ok) {
484			return {
485				ok: false,
486				errors: [{ code: "lesson-id-refused", message: lessonId.error }],
487			};
488		}
489		if (typeof value.title !== "string" || value.title.length === 0) {
490			errors.push({ code: "malformed", message: "deck: missing a title" });
491		}
492		if (!Array.isArray(value.slides)) {
493			return {
494				ok: false,
495				errors: [
496					...errors,
497					{ code: "malformed", message: "deck: slides must be an array" },
498				],
499			};
500		}
501	
502		const slides: DeckSlide[] = [];
503		const seenIds = new Set<string>();
504		value.slides.forEach((raw, index) => {
505			const slide = parseSlide(raw, index, errors);
506			if (!slide) return;
507			if (seenIds.has(slide.id)) {
508				errors.push({
509					code: "duplicate-slide-id",
510					slideId: slide.id,
511					message: `slides[${index}]: slide id is already used`,
512				});
513				return;
514			}
515			seenIds.add(slide.id);
516			slides.push(slide);
517		});
518	
519		checkRetrieval(slides, errors);
520	
521		const entry = lessonEntryById(lessonId.id);
522		const rules = entry.ok ? lessonRules(entry.entry.legacyNumber) : [];
523		for (const slide of slides) {
524			if (slide.kind !== "rule") continue;
525			if (!rules.some((rule) => rule.id === slide.ruleId)) {
526				errors.push({
527					code: "unknown-rule",
528					slideId: slide.id,
529					message: `rule slide "${slide.id}" names a rule this lesson does not declare`,
530				});
531			}
532		}
533	
534		if (errors.length > 0) return { ok: false, errors };
535		return {
536			ok: true,
537			deck: { lessonId: lessonId.id, title: value.title as string, slides },
538		};
539	}
540	
541	/**
542	 * The rendering source for a rule slide: the lesson's own rules-block entry.
543	 * There is no other text on the slide, which is what makes "the lesson applies
544	 * the rule as it states it" checkable at all.
545	 */
546	export function renderRuleSlide(
547		deck: LessonDeck,
548		slide: DeckRuleSlide,
549	): LessonRule | undefined {
