3	import type { LessonContent } from "../../../domain/script/data/lessonContent";
4	import type { LessonSummary } from "../../../domain/script/services/ScriptLessonService";
5	import { DeckSlide } from "./DeckSlide";
6	import {
7		ConsonantCard,
