15	interface Props {
16		summary: LessonSummary;
17		/**
18		 * What this lesson serves — a licensed video or an in-house deck. Already
19		 * resolved by the caller (`LessonPage`/`CatchUpPage`): a lesson that can't
20		 * be resolved at all is that caller's error state, not this component's.
21		 */
22		content: LessonContent;
23		/**
24		 * Skips the video slide even when `content` is the video arm — what
25		 * `CatchUpPage` needs, since a catch-up lesson was already watched the
26		 * first time around. Never affects the deck arm, which a catch-up
27		 * learner sees for the first time either way.
28		 */
29		suppressVideo?: boolean;
30		onComplete: () => void;
31	}
32	
33	interface Slide {
34		type: string;
35		render: () => ReactNode;
36	}
37	
38	function isEmbedUrl(url: string): boolean {
39		return (
40			url.includes("youtube.com") ||
41			url.includes("youtu.be") ||
42			url.includes("vimeo.com")
43		);
44	}
45	
46	function VideoSlide({ url, title }: { url: string; title: string }) {
47		return (
48			<div className="space-y-4">
49				<h2 className="text-lg font-bold text-center">{title}</h2>
50				<div className="relative w-full aspect-video max-h-[40vh] rounded-xl overflow-hidden bg-black">
51					{isEmbedUrl(url) ? (
52						<iframe
53							src={url}
54							title={title}
55							className="absolute inset-0 w-full h-full"
56							allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
57							allowFullScreen
58						/>
59					) : (
60						// biome-ignore lint/a11y/useMediaCaption: Thai pronunciation videos are self-explanatory
61						<video
62							src={url}
63							title={title}
64							className="absolute inset-0 w-full h-full"
65							controls
66							preload="metadata"
67						/>
68					)}
69				</div>
70				<p
71					className="text-sm text-center"
72					style={{ color: "var(--color-text-muted)" }}
73				>
74					Watch the introduction, then continue to learn the symbols.
75				</p>
76			</div>
77		);
78	}
79	
80	export function LessonIntro({
81		summary,
82		content,
83		suppressVideo,
84		onComplete,
85	}: Props) {
86		// A deck lesson stages two phases: the deck itself (which owns its own
87		// stepping, see `DeckSlide`), then the symbol cards below, using this
88		// component's own stepping exactly as the video arm already does. All
89		// hooks below are called unconditionally regardless of phase — the
90		// dispatch happens only in what's returned, never in which hooks run.
91		const [deckDone, setDeckDone] = useState(false);
92		const deckPhase = content.kind === "deck" && !deckDone;
93	
94		const cardSlides: Slide[] = [
95			...summary.consonants.map((c) => ({
96				type: "consonant",
97				render: () => <ConsonantCard c={c} />,
