1	import { beforeEach, describe, expect, it } from "vitest";
2	import { InMemoryStorage } from "../infrastructure/persistence/Storage";
3	import { StorageCardRepository } from "../infrastructure/persistence/StorageCardRepository";
4	import { StorageLearnerStateRepository } from "../infrastructure/persistence/StorageLearnerStateRepository";
5	import { LearningService } from "./script/services/ScriptLessonService";
6	import { ReviewService } from "./session/services/ReviewService";
7	
8	// Cards start at learning step 1 (interval 10 min), so they're due 10 min after creation.
9	// Use a future timestamp to simulate time passing so cards become due.
10	const FUTURE_NOW = new Date(Date.now() + 15 * 60 * 1000).toISOString();
11	
12	describe("Learn-then-Review flow", () => {
13		let storage: InMemoryStorage;
14		let learning: LearningService;
15		let review: ReviewService;
16	
17		beforeEach(() => {
18			storage = new InMemoryStorage();
19			const cardRepo = new StorageCardRepository(storage);
20			const stateRepo = new StorageLearnerStateRepository(storage);
21			learning = new LearningService(cardRepo, stateRepo);
22			review = new ReviewService(cardRepo, stateRepo);
23		});
24	
