1	import { useCallback, useEffect, useState } from "react";
2	import { Button } from "@/presentation/components/ui/button";
3	import {
4		type DeckSlide as DeckSlideData,
5		LESSON_ASSET_ROOT,
6		type LessonDeck,
7		renderRuleSlide,
8		validateDeck,
9	} from "../../../domain/script/data/lessonContent";
10	import { useResetOnCardChange } from "../../hooks/useResetOnCardChange";
11	
12	interface Props {
13		/** Path of the deck's JSON, served from `public/lessons/<id>/deck.json`. */
14		deckPath: string;
15		/** Fires once, when the deck's own last slide is confirmed forward. */
16		onComplete: () => void;
17	}
18	
19	type LoadState =
20		| { readonly status: "loading" }
21		| { readonly status: "error"; readonly message: string }
22		| {
23				readonly status: "ready";
24				readonly deck: LessonDeck;
25				readonly audioUrls: ReadonlyMap<string, string>;
26		  };
27	
28	/**
29	 * Every asset path a deck names for playback must resolve inside its own
30	 * `public/lessons/<lessonId>/` — the trust boundary the deck-JSON sink is
31	 * named against. A URL outside that root, or one containing `..`, is
32	 * refused rather than played — and that refusal is a `console.warn`, not a
33	 * silent drop: a slide with no `audioUrl` at all and a slide whose
34	 * `audioUrl` was refused both end up with no replay button, and only the
35	 * warning tells the two apart.
36	 */
37	/** One raw slide's `id`/`audioUrl`, if both are present as strings. */
38	function readAudioCandidate(
39		item: unknown,
40	): { id: string; audioUrl: string } | undefined {
41		if (typeof item !== "object" || item === null) return undefined;
42		const { id, audioUrl } = item as Record<string, unknown>;
43		if (typeof id !== "string" || typeof audioUrl !== "string") return undefined;
44		return { id, audioUrl };
45	}
46	
47	function extractAudioUrls(
48		raw: unknown,
49		lessonId: string,
50	): ReadonlyMap<string, string> {
51		const map = new Map<string, string>();
52		if (typeof raw !== "object" || raw === null) return map;
53		const slidesRaw = (raw as Record<string, unknown>).slides;
54		if (!Array.isArray(slidesRaw)) return map;
55	
56		const prefix = `${LESSON_ASSET_ROOT}/${lessonId}/`;
57		for (const item of slidesRaw) {
58			const candidate = readAudioCandidate(item);
59			if (!candidate) continue;
60			const { id, audioUrl } = candidate;
61	
62			if (audioUrl.startsWith(prefix) && !audioUrl.includes("..")) {
63				map.set(id, audioUrl);
64				continue;
65			}
66			console.warn(
67				`DeckSlide: refusing audioUrl outside "${prefix}" for slide "${id}": ${audioUrl}`,
68			);
69		}
70		return map;
71	}
72	
73	/**
74	 * True only for a deck that is structurally sound and simply has no slides
75	 * yet: `slides` is an empty array and the retrieval invariant
76	 * (`missing-retrieval`) is the *only* reported error — meaning `lessonId` and
77	 * `title` already passed validation. Any other error, or any actual slide,
78	 * routes to the ordinary failure state instead.
79	 */
80	function isUnauthoredEmptyDeck(
81		raw: unknown,
82		errors: readonly { readonly code: string }[],
83	): boolean {
84		if (typeof raw !== "object" || raw === null) return false;
85		const slides = (raw as Record<string, unknown>).slides;
86		if (!Array.isArray(slides) || slides.length > 0) return false;
87		return errors.length === 1 && errors[0]?.code === "missing-retrieval";
88	}
89	
90	function ReplayButton({ url }: { url: string }) {
91		return (
92			<button
93				type="button"
94				onClick={() => {
95					new Audio(url).play().catch(() => {});
96				}}
97				className="inline-flex items-center justify-center w-12 h-12 rounded-full text-2xl transition-colors"
98				style={{
99					background: "var(--color-surface-2)",
100					color: "var(--color-primary)",
101				}}
102				aria-label="Replay audio"
103			>
104				🔊
105			</button>
106		);
107	}
108	
109	/** Renders the one currently-visible slide of an already-loaded deck. */
110	function DeckSlideContent({
111		deck,
112		slide,
113		audioUrl,
114	}: {
115		deck: LessonDeck;
116		slide: DeckSlideData;
117		audioUrl?: string;
118	}) {
119		// Reveal state for a "reveal" slide, mirroring `Flashcard.tsx`'s own
120		// click-to-reveal pattern — the established mechanism in this repo, not a
121		// second one. Reset (and re-triggered playback below) keys on the slide's
122		// own identity so two consecutive slides that happen to share one audio
123		// clip still reset — see AC5.
124		const [revealed, setRevealed] = useState(false);
125		useResetOnCardChange(slide.id, () => {
126			setRevealed(false);
127		});
128	
129		// biome-ignore lint/correctness/useExhaustiveDependencies: keys on the slide's own identity, not on audioUrl — two consecutive slides sharing a clip must still reset (see AC5)
130		useEffect(() => {
131			if (audioUrl && slide.kind !== "reveal") {
132				new Audio(audioUrl).play().catch(() => {});
133			}
134		}, [slide.id]);
135	
136		// A "reveal" slide's audio is the answer's pronunciation, so it plays on
137		// reveal rather than on arrival — hearing it first would answer the
138		// retrieval step it follows. Mirrors `Flashcard.tsx`'s own reveal-time
139		// audio effect.
140		// biome-ignore lint/correctness/useExhaustiveDependencies: fires once per reveal, not on every audioUrl/slide identity change
141		useEffect(() => {
142			if (revealed && audioUrl) {
143				new Audio(audioUrl).play().catch(() => {});
144			}
145		}, [revealed]);
146	
147		switch (slide.kind) {
148			case "exposition":
149				return (
150					<div className="space-y-4">
151						<h2 className="text-lg font-bold text-center">{slide.heading}</h2>
152						<div className="space-y-2">
153							{slide.body.map((paragraph, i) => (
154								// biome-ignore lint/suspicious/noArrayIndexKey: body is a static ordered list of paragraphs with no other identity
155								<p key={i} className="text-center">
156									{paragraph}
157								</p>
158							))}
159						</div>
160						{audioUrl && (
161							<div className="flex justify-center">
162								<ReplayButton url={audioUrl} />
163							</div>
164						)}
165					</div>
166				);
167			case "retrieval":
168				// The answer lives on the reveal slide this one names, never here — the
169				// schema itself refuses a retrieval slide that carries one.
170				return (
