	classType: "low",
	initialSound: "m",
	finalSound: "m",
	hasDeadEnding: false,
	isAspirated: false,
};

const SUMMARY: LessonSummary = {
	lessonNumber: 1,
	title: "Lesson One",
	focus: "Introduction",
	consonants: [CONSONANT, { ...CONSONANT, character: "น" }],
	vowels: [],
	toneMarks: [],
	rareVowels: [],
	numerals: [],
	toneRules: [],
};

const DECK_PATH = "/thai-script/lessons/lesson-01/deck.json";
