const CATCH_UP_DECK_CONTENT: LessonContent = {
	kind: "deck",
	deckPath: CATCH_UP_DECK_PATH,
};

const VALID_DECK = {
	lessonId: "lesson-01",
	title: "A lesson",
	slides: [
		{
			kind: "exposition",
