tool_use_result.originalFile:
import { useMemo, useState } from "react";
import { useNavigate } from "react-router";
import type {
	ConsonantSummary,
	NumeralSummary,
	RareVowelSummary,
	ToneMarkSummary,
	ToneRuleSummary,
	VowelSummary,
} from "../../domain/script/services/ScriptLessonService";
import { SrsStage } from "../../domain/srs/value-objects/SrsStage";
import { ClassBadge } from "../components/atoms/ClassBadge";
import {
	type ItemCard,
	StageOverrideSheet,
} from "../components/organisms/StageOverrideSheet";
import {
	ConsonantCard,
	NumeralCard,
	RareVowelCard,
	ToneMarkCard,
	ToneRuleCard,
	VowelCard,
} from "../components/organisms/SymbolCard";
import { useApp } from "../hooks/useApp";
import { withDottedCircles } from "../utils/thaiText";

type Tab =
	| "consonants"
	| "vowels"
	| "toneMarks"
	| "toneRules"
	| "rareVowels"
	| "numerals";

function TileAudioButton({ audioUrl }: { audioUrl: string }) {
	return (
		// biome-ignore lint/a11y/useSemanticElements: interactive span with role="button" is intentional for inline audio trigger
		<span
			role="button"
			tabIndex={0}
			onClick={(e) => {
				e.stopPropagation();
				new Audio(audioUrl).play();
			}}
			onKeyDown={(e) => {
				if (e.key === "Enter") {
					e.stopPropagation();
					new Audio(audioUrl).play();
				}
			}}
			className="absolute top-1 right-1 text-xs opacity-50 hover:opacity-100 cursor-pointer"
			aria-label="Play pronunciation"
		>
			🔊
		</span>
	);
}

export function propertyLabel(property: string): string {
	const labels: Record<string, string> = {
		recognition: "Recognition",
		class: "Class",
		initialSound: "Initial Sound",
		finalSound: "Final Sound",
		deadLive: "Dead / Live",
		audioRecognition: "Audio Recognition",
		length: "Length",
		position: "Position",
		effectPerClass: "Effect per Class",
		pronunciation: "Pronunciation",
		value: "Value",
		word: "Word",
		romanization: "Romanization",
		toneRule: "Tone Rule",
	};
	return labels[property] ?? property;
}

export function LearnedItemsPage() {
	const { state, lesson, items, refresh } = useApp();
	const [tab, setTab] = useState<Tab>("consonants");
	const [selectedIdx, setSelectedIdx] = useState<number | null>(null);
	const [overrideOpen, setOverrideOpen] = useState(false);
	const navigate = useNavigate();

	// Collect all learned items across completed lessons
	const {
		consonants,
		vowels,
		toneMarks,
		toneRules,
		rareVowels,
		numerals,
		videos,
	} = useMemo(() => {
		const c: ConsonantSummary[] = [];
		const v: VowelSummary[] = [];
		const t: ToneMarkSummary[] = [];
		const tr: ToneRuleSummary[] = [];
		const rv: RareVowelSummary[] = [];
		const nm: NumeralSummary[] = [];
		const vids: LessonSummary[] = [];

		for (const lessonNum of [...state.completedLessons].sort((a, b) => a - b)) {
			const summary = lesson.getScriptSummary(lessonNum);
			c.push(...summary.consonants);
			v.push(...summary.vowels);
			t.push(...summary.toneMarks);
			tr.push(...summary.toneRules);
			rv.push(...summary.rareVowels);
			nm.push(...summary.numerals);
			if (summary.videoUrl) {
				vids.push(summary);
			}
		}

		return {
			consonants: c,
			vowels: v,
			toneMarks: t,
			toneRules: tr,
			rareVowels: rv,
			numerals: nm,
			videos: vids,
		};
	}, [state.completedLessons, lesson]);

	const vocabWordCount = useMemo(() => {
		const seen = new Set<string>();
		for (const card of Object.values(state.vocabCards)) {
			seen.add(card.id.split(":")[1] ?? "");
		}
		return seen.size;
	}, [state.vocabCards]);

	const selectedSymbol = useMemo(() => {
		if (selectedIdx === null) return null;
		if (tab === "consonants") return consonants[selectedIdx] ?? null;
		if (tab === "vowels") return vowels[selectedIdx] ?? null;
		if (tab === "toneMarks") return toneMarks[selectedIdx] ?? null;
		if (tab === "rareVowels") return rareVowels[selectedIdx] ?? null;
		if (tab === "numerals") return numerals[selectedIdx] ?? null;
		return null;
	}, [tab, selectedIdx, consonants, vowels, toneMarks, rareVowels, numerals]);

	// Tone rules aren't glyphs (no `.character`), so they're tracked separately
	// and matched to their single review card by id rather than symbolCharacter.
	const selectedToneRule = useMemo(() => {
		if (tab !== "toneRules" || selectedIdx === null) return null;
		return toneRules[selectedIdx] ?? null;
	}, [tab, selectedIdx, toneRules]);

	const overrideCards: ItemCard[] = useMemo(() => {
		if (selectedToneRule) {
			return Object.values(state.cards)
				.filter((card) => card.id === selectedToneRule.id)
				.map((card) => ({
					id: card.id,
					pool: "script" as const,
					label: propertyLabel(card.property),
					currentStage: SrsStage.fromScheduleData(
						card.srs.learningStep,
						card.srs.interval,
					),
				}));
		}
		if (!selectedSymbol) return [];
		return Object.values(state.cards)
			.filter((card) => card.symbolCharacter === selectedSymbol.character)
			.map((card) => ({
				id: card.id,
				pool: "script" as const,
				label: propertyLabel(card.property),
				currentStage: SrsStage.fromScheduleData(
					card.srs.learningStep,
					card.srs.interval,
				),
			}));
	}, [selectedSymbol, selectedToneRule, state.cards]);

	const tabs: { key: Tab; label: string; count: number }[] = [
		{ key: "consonants", label: "Consonants", count: consonants.length },
		{ key: "vowels", label: "Vowels", count: vowels.length },
		{ key: "toneMarks", label: "Tones", count: toneMarks.length },
		{ key: "toneRules", label: "Tone Rules", count: toneRules.length },
		...(rareVowels.length > 0
			? [
					{
						key: "rareVowels" as const,
						label: "Rare Vowels",
						count: rareVowels.length,
					},
				]
			: []),
		...(numerals.length > 0
			? [
					{
						key: "numerals" as const,
						label: "Numerals",
						count: numerals.length,
					},
				]
			: []),
		{ key: "videos", label: "Videos", count: videos.length },
	];

	const total =
		consonants.length +
		vowels.length +
		toneMarks.length +
		toneRules.length +
		rareVowels.length +
		numerals.length +
		vocabWordCount;

	if (total === 0) {
		return (
			<div className="text-center py-16 space-y-4">
				<span className="text-6xl">📚</span>
				<h1 className="text-2xl font-bold">No items learned yet</h1>
				<p style={{ color: "var(--color-text-muted)" }}>
					Complete a lesson to see your learned symbols here.
				</p>
			</div>
		);
	}

	return (
		<div className="space-y-6 py-4">
			<div className="flex items-center gap-3">
				<h1 className="text-2xl font-bold flex-1">Learned Items</h1>
				{/* Words live on the Dictionary page, under its "Learned" scope. */}
				<button
					type="button"
					onClick={() => navigate("/dictionary")}
					className="text-sm hover:underline"
					style={{ color: "var(--color-primary)" }}
				>
					{vocabWordCount} word{vocabWordCount === 1 ? "" : "s"} &rarr;
				</button>
			</div>

			{/* Tabs */}
			<div className="overflow-x-auto -mx-4 px-4 [&::-webkit-scrollbar]:hidden [-ms-overflow-style:none] [scrollbar-width:none]">
				<div
					className="flex gap-1 rounded-xl p-1 w-max min-w-full"
					style={{ background: "var(--color-surface-2)" }}
				>
					{tabs.map(({ key, label, count }) => (
						<button
							type="button"
							key={key}
							onClick={() => {
								setTab(key);
								setSelectedIdx(null);
							}}
							className="shrink-0 py-2 px-3 rounded-lg text-sm font-medium transition-colors"
							style={
								tab === key
									? {
											background: "var(--color-surface)",
											color: "var(--color-text)",
											boxShadow:
												"0 1px 3px color-mix(in srgb, var(--color-text) 10%, transparent)",
										}
									: { color: "var(--color-text-muted)" }
							}
						>
							{label}{" "}
							<span
								className="text-xs"
								style={{ color: "var(--color-text-muted)" }}
							>
								({count})
							</span>
						</button>
					))}
				</div>
			</div>

			{/* Detail view */}
			{selectedIdx !== null && tab !== "videos" && (
				<div
					className="border rounded-xl p-4"
					style={{ borderColor: "var(--color-border)" }}
				>
					<button
						type="button"
						onClick={() => {
							setSelectedIdx(null);
							setOverrideOpen(false);
						}}
						className="text-sm mb-4 hover:underline"
						style={{ color: "var(--color-primary)" }}
					>
						← Back to list
					</button>
					{tab === "consonants" && consonants[selectedIdx] && (
						<ConsonantCard c={consonants[selectedIdx]} />
					)}
					{tab === "vowels" && vowels[selectedIdx] && (
						<VowelCard v={vowels[selectedIdx]} />
					)}
					{tab === "toneMarks" && toneMarks[selectedIdx] && (
						<ToneMarkCard t={toneMarks[selectedIdx]} />
					)}
					{tab === "rareVowels" && rareVowels[selectedIdx] && (
						<RareVowelCard v={rareVowels[selectedIdx]} />
					)}
					{tab === "numerals" && numerals[selectedIdx] && (
						<NumeralCard n={numerals[selectedIdx]} />
					)}
					{tab === "toneRules" && toneRules[selectedIdx] && (
						<ToneRuleCard description={toneRules[selectedIdx].description} />
					)}
					{(selectedSymbol || selectedToneRule) && (
						<>
							<button
								type="button"
								onClick={() => setOverrideOpen(true)}
								className="mt-4 w-full py-2 px-4 rounded-lg text-sm font-medium transition-colors"
								style={{
									background:
										"color-mix(in srgb, var(--color-primary) 12%, var(--color-surface))",
									color: "var(--color-primary)",
									border:
										"1px solid color-mix(in srgb, var(--color-primary) 30%, transparent)",
								}}
							>
								Override Stage
							</button>
							<StageOverrideSheet
								open={overrideOpen}
								onClose={() => setOverrideOpen(false)}
								itemLabel={
									selectedToneRule
										? selectedToneRule.description
										: (selectedSymbol?.character ?? "")
								}
								cards={overrideCards}
								onOverride={(id, pool, stage) => {
									items.overrideCardStage(id, pool, stage);
									refresh();
								}}
							/>
						</>
					)}
				</div>
			)}

			{/* Grid view */}
			{selectedIdx === null && tab === "consonants" && (
				<div className="grid grid-cols-4 gap-2">
					{consonants.map((c, i) => (
						<button
							type="button"
							key={c.character}
							onClick={() => setSelectedIdx(i)}
							className="relative flex flex-col items-center p-3 rounded-xl transition-colors"
							style={{ background: "var(--color-surface-2)" }}
						>
							{c.audioUrl && <TileAudioButton audioUrl={c.audioUrl} />}
							<span className="thai text-4xl">
								{withDottedCircles(c.character)}
							</span>
							<span
								className="text-[10px] mt-1 truncate w-full text-center"
								style={{ color: "var(--color-text-muted)" }}
							>
								{c.nameRomanized}
							</span>
							<ClassBadge classType={c.classType} />
						</button>
					))}
				</div>
			)}

			{selectedIdx === null && tab === "vowels" && (
				<div className="grid grid-cols-4 gap-2">
					{vowels.map((v, i) => (
						<button
							type="button"
							key={v.character}
							onClick={() => setSelectedIdx(i)}
							className="relative flex flex-col items-center p-3 rounded-xl transition-colors"
							style={{ background: "var(--color-surface-2)" }}
						>
							{v.audioUrl && <TileAudioButton audioUrl={v.audioUrl} />}
							<span className="thai text-4xl">
								{withDottedCircles(v.character)}
							</span>
							<span
								className="text-[10px] mt-1"
								style={{ color: "var(--color-text-muted)" }}
							>
								{v.name}
							</span>
							<span
								className="text-[10px] mt-0.5 px-1.5 rounded"
								style={{
									background:
										v.length === "long"
											? "color-mix(in srgb, var(--color-enlightened) 15%, var(--color-surface))"
											: "color-mix(in srgb, var(--color-guru) 15%, var(--color-surface))",
									color:
										v.length === "long"
											? "var(--color-enlightened)"
											: "var(--color-guru)",
								}}
							>
								{v.length}
							</span>
						</button>
					))}
				</div>
			)}

			{selectedIdx === null && tab === "toneMarks" && (
				<div className="grid grid-cols-4 gap-2">
					{toneMarks.map((t, i) => (
						<button
							type="button"
							key={t.character}
							onClick={() => setSelectedIdx(i)}
							className="relative flex flex-col items-center p-3 rounded-xl transition-colors"
							style={{ background: "var(--color-surface-2)" }}
						>
							{t.audioUrl && <TileAudioButton audioUrl={t.audioUrl} />}
							<span className="thai text-4xl">
								{withDottedCircles(t.character)}
							</span>
							<span
								className="text-[10px] mt-1"
								style={{ color: "var(--color-text-muted)" }}
							>
								{t.name}
							</span>
						</button>
					))}
				</div>
			)}

			{selectedIdx === null && tab === "toneRules" && (
				<div className="space-y-2">
					{toneRules.map((r, i) => (
						<button
							type="button"
							key={r.id}
							onClick={() => setSelectedIdx(i)}
							className="w-full text-left p-3 rounded-xl text-sm transition-colors"
							style={{ background: "var(--color-surface-2)" }}
						>
							{r.description}
						</button>
					))}
				</div>
			)}

			{selectedIdx === null && tab === "rareVowels" && (
				<div className="grid grid-cols-4 gap-2">
					{rareVowels.map((v, i) => (
						<button
							type="button"
							key={v.character}
							onClick={() => setSelectedIdx(i)}
							className="relative flex flex-col items-center p-3 rounded-xl transition-colors"
							style={{ background: "var(--color-surface-2)" }}
						>
							<span className="thai text-4xl">
								{withDottedCircles(v.character)}
							</span>
							<span
								className="text-[10px] mt-1"
								style={{ color: "var(--color-text-muted)" }}
							>
								{v.name}
							</span>
						</button>
					))}
				</div>
			)}

			{selectedIdx === null && tab === "numerals" && (
				<div className="grid grid-cols-4 gap-2">
					{numerals.map((n, i) => (
						<button
							type="button"
							key={n.character}
							onClick={() => setSelectedIdx(i)}
							className="relative flex flex-col items-center p-3 rounded-xl transition-colors"
							style={{ background: "var(--color-surface-2)" }}
						>
							<span className="thai text-4xl">{n.character}</span>
							<span
								className="text-[10px] mt-1"
								style={{ color: "var(--color-text-muted)" }}
							>
								{n.word} ({n.arabic})
							</span>
						</button>
					))}
				</div>
			)}

			{tab === "videos" && selectedIdx === null && (
				<div className="space-y-3">
					{videos.map((lesson, i) => (
						<button
							type="button"
							key={lesson.lessonNumber}
							onClick={() => setSelectedIdx(i)}
							className="w-full flex items-center gap-4 p-4 rounded-xl transition-colors text-left"
							style={{ background: "var(--color-surface-2)" }}
						>
							<div
								className="flex-shrink-0 w-12 h-12 rounded-xl flex items-center justify-center font-bold text-lg"
								style={{
									background:
										"color-mix(in srgb, var(--color-primary) 12%, var(--color-surface))",
									color: "var(--color-primary)",
								}}
							>
								{lesson.lessonNumber}
							</div>
							<div className="min-w-0">
								<div className="font-semibold truncate">{lesson.title}</div>
								<div
									className="text-sm truncate"
									style={{ color: "var(--color-text-muted)" }}
								>
									{lesson.focus}
								</div>
							</div>
						</button>
					))}
				</div>
			)}

			{tab === "videos" && selectedIdx !== null && videos[selectedIdx] && (
				<VideoPlayer
					lesson={videos[selectedIdx]}
					onBack={() => setSelectedIdx(null)}
				/>
			)}
		</div>
	);
}

